// GithubHeartbeat.jsx
import React, { useState, useEffect, useContext } from 'react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Curve
} from 'recharts';

/**
 * Transforms the weekly contribution data into a sorted array of daily contributions.
 * Each item is { date: 'YYYY-MM-DD', count: contributionCount }.
 */
function transformContributionDays(weeks) {
  let days = [];
  weeks.forEach(week => {
    days = days.concat(week.contributionDays);
  });
  return days
    .map(day => ({ date: day.date, count: day.contributionCount }))
    .sort((a, b) => new Date(a.date) - new Date(b.date));
}

// Custom curve to make the wave more pronounced
const CustomCurve = (props) => {
  const { points, ...rest } = props;
  // Increase the amplitude of the wave
  const enhancedPoints = points.map((point, index) => {
    // Add some randomness to make it more wave-like
    const randomFactor = Math.sin(index * 0.5) * 10;
    return {
      ...point,
      y: point.y + randomFactor
    };
  });

  return <Curve {...rest} points={enhancedPoints} />;
};

// Custom tooltip component to display date and activity
const CustomTooltip = ({ active, payload, label, isDarkMode }) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    const date = new Date(data.date);
    const formattedDate = date.toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric', 
      year: 'numeric' 
    });

    const activityCount = Math.floor(data.originalCount || data.count);
    const activityText = activityCount === 1 ? 'contribution' : 'contributions';

    return (
      <div style={{
        backgroundColor: isDarkMode ? 'rgba(28, 9, 63, 0.9)' : 'rgba(255, 255, 255, 0.9)',
        border: `1px solid ${isDarkMode ? '#8884d8' : '#571ce0'}`,
        borderRadius: '4px',
        padding: '8px 12px',
        boxShadow: '0 2px 10px rgba(0, 0, 0, 0.2)',
        color: isDarkMode ? '#fff' : '#000',
        fontSize: '14px',
        fontFamily: "'SF Pro Display', sans-serif",
        pointerEvents: 'auto',
      }}>
        <p style={{ margin: '0 0 4px 0', fontWeight: 500 }}>{formattedDate}</p>
        <p style={{ margin: 0 }}>
          <span style={{ 
            color: isDarkMode ? '#c792ea' : '#571ce0',
            fontWeight: 600 
          }}>
            {activityCount}
          </span> {activityText}
        </p>
      </div>
    );
  }

  return null;
};

const GithubHeartbeat = () => {
  const [waveData, setWaveData] = useState([]);
  const [totalActivity, setTotalActivity] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [windowHeight, setWindowHeight] = useState(window.innerHeight);
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);

  useEffect(() => {
    // Update window dimensions on resize
    const handleResize = () => {
      setWindowHeight(window.innerHeight);
      setWindowWidth(window.innerWidth);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    // Check if we're in dark mode by looking at the background color
    const checkDarkMode = () => {
      const bgColor = window.getComputedStyle(document.body).backgroundColor;
      // If the background is dark, we're in dark mode
      setIsDarkMode(bgColor.includes('rgb(12, 15, 51)') || bgColor.includes('rgb(28, 9, 63)'));
    };

    checkDarkMode();
    // Listen for changes to the background color
    const observer = new MutationObserver(checkDarkMode);
    observer.observe(document.body, { attributes: true, attributeFilter: ['style'] });

    return () => observer.disconnect();
  }, []);

  // Generate beautiful wave data
  useEffect(() => {
    const generateWaveData = () => {
      setLoading(true);

      const data = [];
      const today = new Date();
      let totalCount = 0;

      // Generate a full year of data plus some extra for a longer wave
      for (let i = 500; i >= 0; i -= 1) {
        const date = new Date();
        date.setDate(today.getDate() - i);

        // Create multiple wave patterns with different frequencies
        const dayOfYear = Math.floor((date - new Date(date.getFullYear(), 0, 0)) / (1000 * 60 * 60 * 24));

        // Primary wave pattern (medium frequency)
        const primaryWave = Math.sin(dayOfYear * 0.05) * 2.5;

        // Secondary wave pattern (higher frequency)
        const secondaryWave = Math.sin(dayOfYear * 0.15) * 1.2;

        // Tertiary wave pattern (very low frequency)
        const tertiaryWave = Math.sin(dayOfYear * 0.01) * 3;

        // Combine waves and add some randomness
        let baseValue = primaryWave + secondaryWave + tertiaryWave;
        baseValue = baseValue + 5; // Shift up to avoid negative values

        // Add some randomness but with patterns
        // More activity on weekdays, less on weekends
        const dayOfWeek = date.getDay();
        const weekdayBoost = (dayOfWeek > 0 && dayOfWeek < 6) ? 1.5 : 0.5;

        // Seasonal patterns - more activity in certain months
        const month = date.getMonth();
        const seasonalFactor = [0.8, 0.9, 1.0, 1.2, 1.3, 1.5, 1.4, 1.2, 1.1, 1.0, 0.9, 1.1][month];

        // Random daily variation
        const randomFactor = Math.random() * 2;

        // Calculate final count
        const count = Math.max(0, (baseValue * weekdayBoost * seasonalFactor) + randomFactor);
        const roundedCount = Math.floor(count);
        totalCount += roundedCount;

        data.push({
          date: date.toISOString().split('T')[0],
          count: count,
          originalCount: roundedCount
        });
      }

      // Sort by date
      data.sort((a, b) => new Date(a.date) - new Date(b.date));

      setWaveData(data);
      setTotalActivity(totalCount);
      setLoading(false);
    };

    generateWaveData();
  }, []);

  // Calculate the height as 1/4 of the viewport height
  const waveHeight = Math.floor(windowHeight / 4);

  const waveContainerStyle = {
    position: 'fixed',
    bottom: 0,
    left: 0,
    width: '100%',
    height: `${waveHeight}px`,
    zIndex: 1,
    pointerEvents: 'auto', // Allow hover interactions
    overflow: 'hidden',
  };

  const waveContentStyle = {
    position: 'absolute',
    bottom: '20px',
    left: '20px',
    color: isDarkMode ? 'rgba(255, 255, 255, 0.7)' : 'rgba(0, 0, 0, 0.7)',
    zIndex: 2,
    pointerEvents: 'auto', // Make text clickable
    fontSize: '12px',
    fontWeight: 300,
    textShadow: isDarkMode ? '0 1px 2px rgba(0,0,0,0.3)' : 'none',
  };

  // Colors for light and dark mode
  const primaryColor = isDarkMode ? '#8884d8' : '#571ce0';
  const secondaryColor = isDarkMode ? '#c792ea' : '#8884d8';

  return (
    <div style={waveContainerStyle}>
      <div style={waveContentStyle}>
        {loading ? 'Generating activity wave...' : `${totalActivity.toLocaleString()} contributions visualized`}
      </div>
      <div style={{ width: '100%', height: '100%' }}>
        <ResponsiveContainer>
          <AreaChart 
            data={waveData}
            margin={{ top: 0, right: 0, left: 0, bottom: 0 }}
          >
            <defs>
              <linearGradient id="colorContributions" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={primaryColor} stopOpacity={0.6} />
                <stop offset="95%" stopColor={secondaryColor} stopOpacity={0.1} />
              </linearGradient>
            </defs>
            <Tooltip 
              content={<CustomTooltip isDarkMode={isDarkMode} />}
              cursor={{ stroke: isDarkMode ? 'rgba(255,255,255,0.3)' : 'rgba(0,0,0,0.3)', strokeWidth: 1 }}
            />
            <Area
              type="basis" // Smooth, wavy curve
              dataKey="count"
              stroke={primaryColor}
              strokeWidth={2}
              fillOpacity={1}
              fill="url(#colorContributions)"
              animationDuration={2000}
              isAnimationActive={true}
              activeDot={{ 
                r: 6, 
                fill: isDarkMode ? '#c792ea' : '#571ce0',
                stroke: isDarkMode ? '#1C093F' : '#fff',
                strokeWidth: 2
              }}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default GithubHeartbeat;
